<?php
$report=$analyticsReport;$current=$report['current'];$previous=$report['previous'];$mode=$report['mode'];
$analyticsValue=static function($value,string $type='money'):string {
    if($value===null)return $type==='money'?'Menunggu data keuangan/HPP':'—';
    return match($type){'percent'=>number_format((float)$value,1,',','.').'%', 'ratio'=>number_format((float)$value,2,',','.').'x','count'=>number_format((float)$value,0,',','.'),default=>formatRp($value)};
};
$spark=static function(array $values,string $color):string {
    if(count($values)<2||in_array(null,$values,true))return '';
    $min=min($values);$max=max($values);$range=max(1,$max-$min);$points=[];
    foreach($values as $i=>$value)$points[]=round($i/(count($values)-1)*220,2).','.round(32-($value-$min)/$range*27,2);
    return '<svg viewBox="0 0 220 38" class="w-full h-10 mt-3" aria-hidden="true"><polyline fill="none" stroke="'.$color.'" stroke-width="1.5" points="'.implode(' ',$points).'"/></svg>';
};
$kpiLabels=['revenue'=>['Total Omzet','money'],'net_income'=>['Omzet Setelah Potongan Marketplace','money'],'gross_profit'=>['Laba Kotor','money'],'net_profit'=>['Laba Bersih','money'],'roas'=>['ROAS','ratio'],'gross_margin'=>['% Laba Kotor','percent'],'net_margin'=>['% Laba Bersih','percent'],'pending_revenue'=>['Uang Berpotensi Cair (Omzet)','money'],'pending_net'=>['Uang Berpotensi Cair (Setelah Potongan)','money']];
$chosen=$current[$mode];$projects=$current['by_store'];
$winner=static function(array $projects,string $mode,string $key):string {
    $eligible=array_values(array_filter($projects,static fn($row)=>$row[$mode]['orders']>0&&$row[$mode][$key]!==null));
    if(!$eligible)return 'Belum ada data';
    usort($eligible,static fn($a,$b)=>$b[$mode][$key]<=>$a[$mode][$key]);return $eligible[0]['store']['store_name'];
};
$endpointParams=['store_filter'=>$globalFilters['store_id']??'','platform'=>$globalFilters['platform']??'','date_start'=>$report['start'],'date_end'=>$report['end'],'date_basis'=>$report['date_basis'],'analytics_mode'=>$mode,'analytics_stores'=>$globalFilters['analytics_stores']??[],'include_disconnected'=>!empty($globalFilters['include_disconnected'])?'1':''];
?>
