            $color=in_array($key,['revenue','net_income'],true)?'#3b82f6':(str_contains($key,'pending')?'#0d9488':'#16a34a');
        ?><article class="rounded-2xl border border-slate-100 bg-white p-4 shadow-sm" style="background:linear-gradient(135deg,<?= $color ?>0d,white);border-bottom:2px solid <?= $color ?>33"><p class="text-[11px] text-slate-500 min-h-8"><?= $label ?></p><p class="font-extrabold text-lg" style="color:<?= $value!==null&&$value<0?'#ef4444':$color ?>"><?= $analyticsValue($value,$type) ?></p><?php if(in_array($key,['revenue','net_income','gross_profit','net_profit'],true)): ?><p class="text-[10px] text-slate-400 mt-1"><?= $delta===null?'Pembanding belum tersedia':(($delta>=0?'+':'').number_format($delta,1,',','.').'% vs periode sebelumnya') ?></p><?= $spark(array_map(static fn($day)=>$day[$bucket][$key],array_values($current['daily'])),$color) ?><?php endif; ?></article><?php endforeach; ?>
    </div></div>
