    <div class="overflow-auto rounded-2xl border bg-white"><table class="w-full text-xs whitespace-nowrap"><thead class="text-[10px] uppercase text-slate-500 bg-slate-50"><tr><th class="p-3 text-left">Proyek</th><?php foreach(['Pendapatan/Omzet','Biaya Marketplace','HPP','Laba Kotor','% Laba Kotor','Pengeluaran','Penyesuaian','Laba Bersih','% Laba Bersih','Pesanan'] as $label): ?><th class="p-3 text-right"><?= $label ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y"><?php foreach($projects as $project):$row=$project[$mode]; ?><tr class="<?= $row['net_profit']<0?'bg-rose-50/50':'hover:bg-emerald-50/50' ?>"><td class="p-3 font-bold"><?= htmlspecialchars($project['store']['store_name']) ?><span class="block font-normal text-[10px] text-slate-400"><?= htmlspecialchars($project['store']['platform']) ?></span></td><?php foreach(['revenue'=>'money','fees'=>'money','cogs'=>'money','gross_profit'=>'money','gross_margin'=>'percent','expenses'=>'money','adjustments'=>'money','net_profit'=>'money','net_margin'=>'percent','orders'=>'count'] as $key=>$type): ?><td class="p-3 text-right <?= in_array($key,['fees','cogs','expenses'],true)||($row[$key]!==null&&$row[$key]<0)?'text-rose-600':'text-slate-700' ?>"><?= $analyticsValue($row[$key],$type) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$projects): ?><tr><td colspan="11" class="p-8 text-center text-slate-400">Tidak ada toko pada filter ini.</td></tr><?php endif; ?></tbody></table></div>
    <div class="grid md:grid-cols-3 gap-3"><?php foreach(['Top Performer (Omzet)'=>'revenue','Best Margin'=>'net_margin','Rata-rata Nilai Pesanan Tertinggi'=>'average_order'] as $label=>$key): ?><div class="bg-white border rounded-xl p-4"><p class="text-xs text-slate-500"><?= $label ?></p><p class="font-bold text-brand-700 mt-2"><?= htmlspecialchars($winner($projects,$mode,$key)) ?></p></div><?php endforeach; ?></div>
    <div><h3 class="font-extrabold text-lg mb-4">Performa Keuangan</h3><div class="grid lg:grid-cols-2 border rounded-2xl bg-white overflow-hidden"><?php foreach(['settled'=>'Berbasis Pesanan Sudah Cair','all'=>'Berbasis Pesanan Sudah Cair + Belum Cair'] as $bucket=>$label): ?><div class="p-5 space-y-3"><h4 class="font-bold text-sm mb-4"><?= $label ?></h4><?php foreach(['revenue'=>'Total Omzet','fees'=>'Total Potongan Marketplace','net_income'=>'Omzet Setelah Potongan Marketplace','cogs'=>'Total HPP','gross_profit'=>'Laba Kotor (Sebelum Penyesuaian)','expenses'=>'Total Pengeluaran','adjustments'=>'Total Penyesuaian','net_profit'=>'Laba Bersih Setelah Penyesuaian'] as $key=>$title): ?><div class="flex justify-between gap-4 text-xs"><span class="text-slate-500"><?= $title ?></span><b class="<?= $current[$bucket][$key]<0||in_array($key,['fees','expenses','cogs'],true)?'text-rose-600':'text-emerald-600' ?>"><?= $analyticsValue($current[$bucket][$key]) ?></b></div><?php endforeach; ?></div><?php endforeach; ?></div></div>
    <?php foreach(['Operasional'=>['orders'=>['Total Pesanan','count'],'average_order'=>['Rata-rata Nilai Pesanan','money'],'adjustments'=>['Total Penyesuaian','money'],'roas'=>['ROAS','ratio']], 'Masalah & Pengembalian'=>['cancelled'=>['Pesanan Batal','count'],'returns'=>['Pesanan Retur','count']], 'Manajemen Pengeluaran Global'=>['expenses'=>['Total Pengeluaran','money'],'ads'=>['Biaya Iklan','money'],'roi'=>['ROI Iklan (Estimasi)','percent'],'roas'=>['ROAS','ratio'],'cost_per_order'=>['Biaya per Transaksi','money'],'expense_ratio'=>['Rasio Pengeluaran/Pendapatan','percent']]] as $heading=>$cards): ?><div><h3 class="font-extrabold text-lg mb-4"><?= $heading ?></h3><div class="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"><?php foreach($cards as $key=>[$label,$type]): ?><div class="bg-white border border-slate-100 rounded-xl p-5 shadow-sm"><p class="text-xs text-slate-500"><?= $label ?></p><p class="font-extrabold text-lg mt-3 <?= in_array($key,['cancelled','expenses','adjustments'],true)?'text-rose-600':'text-emerald-600' ?>"><?= $analyticsValue($heading==='Masalah & Pengembalian'?$current['all'][$key]:$chosen[$key],$type) ?></p></div><?php endforeach; ?></div></div><?php endforeach; ?>
    <div class="bg-white border rounded-2xl p-5"><h3 class="font-bold mb-4">Rincian Biaya Global</h3><div class="space-y-2"><?php foreach($current['fees'][$mode] as $fee):if(abs($fee['amount'])<0.01)continue; ?><div class="flex justify-between items-center gap-4 bg-slate-50 rounded-lg px-3 py-3 text-xs"><div><span class="inline-block w-2 h-2 rounded-full mr-2 <?= $fee['effect']<0?'bg-emerald-500':'bg-rose-500' ?>"></span><?= htmlspecialchars($fee['label']) ?><span class="block ml-4 text-[10px] text-slate-400"><?= $fee['effect']<0?'Kredit / Pengurang Biaya':'Potongan' ?></span></div><b class="<?= $fee['effect']<0?'text-emerald-600':'text-rose-600' ?>"><?= $analyticsValue($fee['amount']) ?></b></div><?php endforeach; ?><?php if(!$current['fees'][$mode]): ?><p class="text-xs text-slate-400">Belum ada rincian biaya pada periode ini.</p><?php endif; ?></div></div>
    <div class="bg-white border rounded-2xl p-5 space-y-5"><h3 class="font-bold">Data Penjualan Harian Global</h3><p class="text-xs text-slate-500">Omzet (hijau), laba bersih (biru), pesanan (ungu), dan retur (oranye). Arahkan ke grafik untuk melihat nilainya.</p>
