        <div class="overflow-auto max-h-96 border rounded-xl"><table class="w-full text-xs whitespace-nowrap"><thead class="sticky top-0 bg-slate-50 text-[10px] text-slate-500 uppercase"><tr><?php foreach(['Tanggal','Omzet','Perubahan','Laba Bersih','Pengeluaran','Retur','Pesanan'] as $label): ?><th class="p-3 text-right"><?= $label ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y"><?php $last=null;$revenues=array_map(static fn($day)=>$day[$mode]['revenue'],$current['daily']);foreach($current['daily'] as $date=>$values):$day=$values[$mode];$change=$last!==null&&$last!=0?($day['revenue']-$last)/abs($last)*100:null;$last=$day['revenue']; ?><tr class="<?= $day['revenue']>0&&$day['revenue']===max($revenues)?'bg-emerald-50':($day['revenue']===min($revenues)&&max($revenues)>0?'bg-rose-50/50':'') ?>"><td class="p-3"><?= htmlspecialchars($date) ?></td><td class="p-3 text-right"><?= $analyticsValue($day['revenue']) ?></td><td class="p-3 text-right <?= ($change??0)<0?'text-rose-600':'text-emerald-600' ?>"><?= $change===null?'—':($change>=0?'+':'').$analyticsValue($change,'percent') ?></td><td class="p-3 text-right"><?= $analyticsValue($day['net_profit']) ?><span class="block text-[10px] text-slate-400"><?= $analyticsValue($day['net_margin'],'percent') ?></span></td><td class="p-3 text-right"><?= $analyticsValue($day['expenses']) ?></td><td class="p-3 text-right"><?= $current['daily'][$date]['all']['returns'] ?></td><td class="p-3 text-right"><?= $day['orders'] ?></td></tr><?php endforeach; ?></tbody></table></div>
